/** Real installed JS exports, native source pages, mutations, pagination and actual audio queue. */
final class SourceBrowserChecks {
    private final Instrumentation test;private final Context context;private MainActivity activity;
    SourceBrowserChecks(Instrumentation test){this.test=test;context=test.getTargetContext();}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private interface Action {void run()throws Exception;}
    private void ui(Action action)throws Exception{Throwable[] failure={null};test.runOnMainSync(()->{try{action.run();}catch(Throwable error){failure[0]=error;}});if(failure[0]!=null)throw new AssertionError("Browser UI action failed",failure[0]);}
    private interface Condition {boolean valid()throws Exception;}
    private void await(Condition condition,String message)throws Exception{long until=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<until){boolean[] value={false};ui(()->value[0]=condition.valid());if(value[0])return;SystemClock.sleep(50);}throw new AssertionError(message);}
    private static Object field(Object target,String name)throws Exception{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);}
    private static void invoke(Object target,String name,Class<?>[] types,Object...args)throws Exception{Method method=target.getClass().getDeclaredMethod(name,types);method.setAccessible(true);method.invoke(target,args);}
    private View find(View root,String text){if(root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View match=find(group.getChildAt(i),text);if(match!=null)return match;}}return null;}
    private View findByDescription(View root,String description){if(root.getContentDescription()!=null&&description.contentEquals(root.getContentDescription()))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View value=findByDescription(group.getChildAt(i),description);if(value!=null)return value;}}return null;}
    private View findText(String text){return find(activity.getWindow().getDecorView(),text);}
    private void click(String text)throws Exception{await(()->findText(text)!=null,"source page text absent: "+text);ui(()->{View view=findText(text);while(view!=null&&!view.isClickable()){android.view.ViewParent parent=view.getParent();view=parent instanceof View?(View)parent:null;}check(view!=null&&view.isEnabled(),"source action disabled: "+text);view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true);check(view.performClick(),"source action did not click: "+text);});test.waitForIdleSync();}
    private JSONObject last(String id)throws Exception{return new JSONObject(context.getSharedPreferences("plugin_data_"+id,0).getString("lastCall","{}"));}
    private void awaitCall(String id,String method)throws Exception{await(()->last(id).optString("method").equals(method),"missing source export: "+method);}
    private SourceBrowser browser()throws Exception{return (SourceBrowser)field(activity,"sourceBrowser");}
    private JSONObject result()throws Exception{Object page=field(browser(),"page");return page==null?null:(JSONObject)field(page,"result");}
    private PluginManager.PluginInfo info(PluginManager manager,String id){for(PluginManager.PluginInfo source:manager.list())if(source.id.equals(id))return source;throw new AssertionError("browser fixture not installed: "+id);}
    private void install(PluginManager manager,String id,String label,String base)throws Exception{
        String script;try(InputStream input=test.getContext().getAssets().open("browser-fixture.js")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[4096];int n;while((n=input.read(block))!=-1)out.write(block,0,n);script=out.toString("UTF-8").replace("__BASE__",base).replace("__LABEL__",label);}
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){zip.putNextEntry(new ZipEntry("plugin.json"));zip.write(new JSONObject().put("id",id).put("name","Browser "+label).put("main","index.js").put("permissions",new JSONObject().put("network",new JSONArray().put("127.0.0.1"))).toString().getBytes("UTF-8"));zip.closeEntry();zip.putNextEntry(new ZipEntry("index.js"));zip.write(script.getBytes("UTF-8"));zip.closeEntry();}
        CountDownLatch done=new CountDownLatch(1);boolean[] success={false};String[] error={""};manager.installZipStream(new ByteArrayInputStream(bytes.toByteArray()),(ok,raw)->{success[0]=ok;error[0]=raw;done.countDown();});check(done.await(30,TimeUnit.SECONDS)&&success[0],"browser fixture install: "+error[0]);context.getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,true).commit();
    }
    void run()throws Exception{
        String alpha="browser-alpha",beta="browser-beta";SharedPreferences prefs=context.getSharedPreferences("library",0);String oldSource=prefs.getString("selected_source","");boolean oldCache=prefs.getBoolean("auto_cache",true);prefs.edit().remove("selected_source").putBoolean("auto_cache",false).commit();
        activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginManager manager=(PluginManager)field(activity,"pluginManager");
        try(AudioServer server=new AudioServer()){
            install(manager,alpha,"Alpha",server.base());install(manager,beta,"Beta",server.base());ui(()->invoke(activity,"refreshSourceTabs",new Class<?>[]{}));
            click("Browser Alpha");await(()->findText("Alpha source home")!=null,"source button only changed color, not the home pane");ui(()->{check(browser().active()&&browser().sourceId().equals(alpha),"source not registered in main pane");Spinner spinner=(Spinner)findByDescription(activity.getWindow().getDecorView(),"搜索类型");check(spinner.getSelectedView() instanceof TextView&&((TextView)spinner.getSelectedView()).getCurrentTextColor()==Color.WHITE,"search kind text is invisible in the dark theme");Rect titleBounds=new Rect();View albumTitle=findText("Alpha album");check(albumTitle!=null&&albumTitle.getGlobalVisibleRect(titleBounds)&&titleBounds.height()==albumTitle.getHeight(),"source card title is outside the phone viewport");});capture();
            click("Alpha album");awaitCall(alpha,"album");click("收藏此专辑");await(()->context.getSharedPreferences("plugin_data_"+alpha,0).getString("saved","").equals("true"),"album save was decorative");await(()->findText("取消收藏此专辑")!=null,"album saved state not rendered");click("返回");click("Alpha artist");awaitCall(alpha,"artist");click("关注此歌手");await(()->context.getSharedPreferences("plugin_data_"+alpha,0).getString("following","").equals("true"),"artist follow not sent");click("返回");
            click("Alpha podcast");awaitCall(alpha,"show");await(()->findText("Alpha episode one  ·  Browser artist")!=null,"podcast episode did not render");click("订阅此播客");await(()->context.getSharedPreferences("plugin_data_"+alpha,0).getString("subscribed","").equals("true"),"podcast subscription not sent");click("加载更多");await(()->result()!=null&&result().optJSONArray("episodes").length()==2,"podcast pagination lost episodes");check(last(alpha).getJSONObject("args").getInt("offset")==1,"podcast source offset wrong");click("Browser publisher");await(()->findText("Alpha publisher")!=null,"publisher custom browse page not opened");click("返回");click("返回");
            click("Alpha station");awaitCall(alpha,"stationNext");await(()->findText("Alpha a  ·  Browser artist")!=null,"stationNext tracks did not render");click("返回");click("Open custom page");await(()->findText("Alpha custom")!=null,"custom page link not opened");click("返回");
            click("Long source page");await(()->findText("显示更多已加载内容 · 60 / 65")!=null,"large source page created all rows at once");String countBefore=context.getSharedPreferences("plugin_data_"+alpha,0).getString("callCount","");ui(()->check(findText("Alpha loaded 64  ·  Browser artist")==null,"large page bypassed bounded rendering"));click("显示更多已加载内容 · 60 / 65");await(()->findText("Alpha loaded 64  ·  Browser artist")!=null,"loaded source rows were silently truncated");check(countBefore.equals(context.getSharedPreferences("plugin_data_"+alpha,0).getString("callCount","")),"showing loaded rows made another source request");click("返回");
            int kindIndex=1;for(String kind:new String[]{"albums","artists","playlists","shows"}){final int selection=kindIndex++;ui(()->((Spinner)findByDescription(activity.getWindow().getDecorView(),"搜索类型")).setSelection(selection));test.waitForIdleSync();await(()->kind.equals(field(activity,"searchKind")),"search kind selection callback missing");ui(()->invoke(activity,"landscapeSearch",new Class<?>[]{String.class},"fixture"));await(()->result()!=null&&result().optJSONArray(kind)!=null,"search kind did not render: "+kind);JSONObject args=last(alpha).getJSONObject("args");check(args.getString("kind").equals(kind)&&args.getInt("offset")==0,"search export parameters lost: "+kind);}
            ui(()->{fieldSet(activity,"searchKind","tracks");invoke(activity,"landscapeSearch",new Class<?>[]{String.class},"fixture");});await(()->result()!=null&&result().optJSONArray("tracks")!=null&&result().optJSONArray("tracks").length()==2,"track search first page missing");click("加载更多");await(()->result()!=null&&result().optJSONArray("tracks").length()==3,"search page deduplication lost or duplicated tracks");check(last(alpha).getJSONObject("args").getInt("offset")==2,"search offset not based on source consumed rows");click("加载更多");await(()->result()!=null&&!result().optBoolean("more"),"empty page left an endless load-more button");check(last(alpha).getJSONObject("args").getInt("offset")==4,"duplicate source row changed the next offset");
            ui(()->invoke(activity,"landscapeSearch",new Class<?>[]{String.class},"slow"));await(()->last(alpha).optString("method").equals("search")&&last(alpha).optJSONObject("args").optString("query").equals("slow"),"delayed search never reached actual JS");click("Browser Beta");await(()->findText("Beta source home")!=null,"source switching did not load the second home");SystemClock.sleep(1600);ui(()->check(findText("Beta source home")!=null&&findText("Alpha stale slow  ·  Browser artist")==null,"old source callback overwrote new content"));
            click("Browser Alpha");await(()->findText("Alpha source home")!=null,"source home did not reload");test.waitForIdleSync();File qa=new File(context.getExternalFilesDir(null),"qa");qa.mkdirs();Bitmap screenshot=test.getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(qa,"source-browser.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();
            ui(()->invoke(activity,"landscapeSearch",new Class<?>[]{String.class},"fixture"));await(()->findText("Alpha a  ·  Browser artist")!=null,"search results missing for playback");click("Alpha a  ·  Browser artist");PlaybackService[] service={null};await(()->{service[0]=(PlaybackService)field(activity,"playbackService");return service[0]!=null&&service[0].snapshot().playing&&service[0].snapshot().title.startsWith("Alpha a");},"browser song did not reach native audio playback");ui(()->{check(service[0].queueSnapshot().length()==2,"source playback used the accumulated global music library");check(browser().active()&&findText("Alpha b  ·  Browser artist")!=null,"playback replaced the source results with local songs");invoke(activity,"next",new Class<?>[]{});});await(()->service[0].snapshot().playing&&service[0].snapshot().title.startsWith("Alpha b"),"next escaped the selected source queue");check(server.authenticated.contains("/a")&&server.authenticated.contains("/b"),"browser source stream headers lost");ui(()->{JSONArray copy=service[0].queueSnapshot();copy.getJSONObject(0).put("uri","broken");check(!service[0].queueSnapshot().getJSONObject(0).optString("uri").equals("broken"),"queue inspection exposed mutable playback state");service[0].playQueueIndex(0);});await(()->service[0].snapshot().playing&&service[0].snapshot().title.startsWith("Alpha a"),"selecting a real queue row failed");
            ArrayList<JSONObject> many=new ArrayList<>();for(int i=0;i<=500;i++)many.add(new JSONObject().put("id","late-"+i).put("name","Late row "+i));ui(()->invoke(activity,"playSourceQueue",new Class<?>[]{PluginManager.PluginInfo.class,ArrayList.class,int.class},info(manager,alpha),many,500));await(()->service[0].snapshot().playing&&service[0].snapshot().title.equals("Late row 500"),"a track after the first queue block could not play");
            click("◎  本地音乐");ui(()->check(!browser().active(),"local library button left source requests active"));
        }finally{ui(()->{PlaybackService service=(PlaybackService)field(activity,"playbackService");if(service!=null)service.stopPlayback();activity.finish();});for(String id:new String[]{alpha,beta}){PluginArchive.delete(new File(context.getFilesDir(),"plugins/"+id));prefs.edit().remove("plugin_network_"+id).remove("plugin_enabled_"+id).commit();}prefs.edit().putString("selected_source",oldSource).putBoolean("auto_cache",oldCache).commit();}
    }
    private void capture()throws Exception{test.waitForIdleSync();File qa=new File(context.getExternalFilesDir(null),"qa");qa.mkdirs();Bitmap bitmap=test.getUiAutomation().takeScreenshot();check(bitmap!=null,"browser screenshot missing");try(FileOutputStream out=new FileOutputStream(new File(qa,"source-browser.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
    private static void fieldSet(Object target,String name,Object value)throws Exception{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);field.set(target,value);}
    private static final class AudioServer implements AutoCloseable {
        private final ServerSocket socket=new ServerSocket(0);final Set<String> authenticated=Collections.synchronizedSet(new HashSet<>());private final byte[] image;
        AudioServer()throws Exception{Bitmap bitmap=Bitmap.createBitmap(80,80,Bitmap.Config.ARGB_8888);bitmap.eraseColor(0xff60769c);ByteArrayOutputStream png=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,png);bitmap.recycle();image=png.toByteArray();Thread worker=new Thread(()->{while(!socket.isClosed())try{Socket client=socket.accept();Thread connection=new Thread(()->serve(client));connection.setDaemon(true);connection.start();}catch(Exception ignored){}});worker.setDaemon(true);worker.start();}
        private void serve(Socket client){try(Socket value=client){value.setSoTimeout(5000);BufferedReader input=new BufferedReader(new InputStreamReader(value.getInputStream(),"US-ASCII"));String request=input.readLine(),line;String path=request.split(" ")[1];boolean authorized=false;while((line=input.readLine())!=null&&!line.isEmpty())if(line.equalsIgnoreCase("X-Source-Token: browser-audio"))authorized=true;if(authorized)authenticated.add(path);boolean cover=path.startsWith("/cover");byte[] body=cover?image:BackgroundPlaybackChecks.wav(20000);value.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: "+(cover?"image/png":"audio/wav")+"\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));value.getOutputStream().write(body);}catch(Exception ignored){}}
        String base(){return "http://127.0.0.1:"+socket.getLocalPort();}
        public void close()throws Exception{socket.close();}
    }
}
